return-response.set-body:
@{
				var jwt = (Jwt)context.Variables["appJwt"];
				var scopes = new JArray(jwt.Claims.GetValueOrDefault("scope", "").Split(' ').Where(s => s.Length > 0).ToArray());
				return new JObject(
					new JProperty("sub", jwt.Subject),
					new JProperty("delegated_identity", (string)context.Variables["delegatedIdentity"]),
					new JProperty("scopes", scopes),
					new JProperty("expires_at", jwt.ExpirationTime.HasValue ? jwt.ExpirationTime.Value.ToString("o") : "")
				).ToString(Newtonsoft.Json.Formatting.None);
			}
